import pyomo.environ as pyo

DATA = {
    "capsules": ["special", "one_daily"],
    "nutrients": ["A", "B"],
    "cost": {
        "special": 0.50,
        "one_daily": 0.20,
    },
    "content": {
        # content[nutrient][capsule] = units of nutrient per capsule
        "A": {"special": 4, "one_daily": 3},
        "B": {"special": 5, "one_daily": 7},
    },
    "requirement": {
        "A": 25,
        "B": 40,
    },
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    # Sets
    model.capsules = pyo.Set(initialize=d["capsules"])
    model.nutrients = pyo.Set(initialize=d["nutrients"])

    # Decision variables: integer number of capsules purchased
    model.buy = pyo.Var(model.capsules, within=pyo.NonNegativeIntegers)

    # Objective: minimize total cost
    def obj_rule(m):
        return sum(d["cost"][i] * m.buy[i] for i in m.capsules)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraints: meet at least the required units of each nutrient
    def nutrient_rule(m, n):
        return sum(d["content"][n][i] * m.buy[i] for i in m.capsules) >= d["requirement"][n]

    model.nutrient_requirement = pyo.Constraint(model.nutrients, rule=nutrient_rule)

    return model


