    "nutrients": ["A", "B"],                       # required nutrients

    # cost per capsule (dollars)
    "cost": {
        "Special": 0.50,
        "OneDaily": 0.20,
    },

    # units of nutrient n per capsule of type i
    "content": {
        ("A", "Special"): 4,
        ("A", "OneDaily"): 3,
        ("B", "Special"): 5,
        ("B", "OneDaily"): 7,
    },

    # minimum daily requirement per nutrient (units)
    "requirement": {
        "A": 25,
        "B": 40,
    },
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    # Sets
    model.I = pyo.Set(initialize=d["capsules"], doc="capsule types")
    model.N = pyo.Set(initialize=d["nutrients"], doc="nutrients")

    # Variables: number of capsules of each type (integer, nonnegative)
    model.x = pyo.Var(model.I, within=pyo.NonNegativeIntegers)

    # Objective: minimise total cost
    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.I)
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraints: one per nutrient, must meet the minimum requirement
    def nutrient_rule(m, n):
        return sum(d["content"][(n, i)] * m.x[i] for i in m.I) >= d["requirement"][n]
    model.nutrient_requirement = pyo.Constraint(model.N, rule=nutrient_rule)

    return model
